
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.784582965858633e+00, -4.690965080659891e+00, -4.559807370999141e+00, -4.378162505766785e+00, -4.130706388389399e+00, -3.801378966667215e+00, -3.377126850650693e+00, -2.853781739936528e+00, -2.240822741407072e+00, -1.568155574895483e+00, -9.663052575283133e-01, -6.720904379790791e-01, -6.185507561784712e-01, -5.253657968185453e-01, -3.706723867785681e-01, -2.145438261791863e-01, -9.683252851539463e-02, -3.219782636089854e-02, -6.908122966523610e-03, -7.768139672550775e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


